export const tracks={
 paris:{name:'Afternoon by the Seine',url:'assets/music/paris-afternoon-seine.mp3'},
 taipei:{name:'淡水河岸的暮色',url:'assets/music/taipei-riverside-dusk.mp3'}
};
// One media element keeps city switches mutually exclusive, including rapid clicks.
export class AmbientPlayer{
 constructor(onState=()=>{},audioFactory=()=>new Audio()) {this.onState=onState;this.volume=.25;this.playing=false;this.city='paris';this.token=0;this.audio=audioFactory();this.audio.preload='none';this.audio.loop=true;this.audio.volume=0;this.fadeTimer=null;this.finishFade=null;this.audio.addEventListener('error',()=>{this.playing=false;this.onState(false,this.city);});}
 fade(target,duration=600){clearInterval(this.fadeTimer);this.finishFade?.();return new Promise(resolve=>{this.finishFade=resolve;const start=this.audio.volume,begin=Date.now();this.fadeTimer=setInterval(()=>{const t=Math.min(1,(Date.now()-begin)/duration);this.audio.volume=start+(target-start)*t;if(t===1){clearInterval(this.fadeTimer);this.fadeTimer=null;this.finishFade=null;resolve();}},25);});}
 setVolume(value){this.volume=Math.max(0,Math.min(1,value));if(this.playing)this.fade(this.volume,150);}
 async play(city){if(!tracks[city])throw Error('此城市尚未提供音樂');const request=++this.token;this.playing=false;if(!this.audio.paused)await this.fade(0);if(request!==this.token)return;this.audio.pause();if(this.city!==city||!this.audio.getAttribute('src')){this.audio.src=tracks[city].url;this.audio.load();}this.city=city;this.audio.volume=0;try{await this.audio.play();}catch(error){if(request===this.token){this.playing=false;this.onState(false,city);}throw error;}if(request!==this.token)return;this.playing=true;this.onState(true,city);this.fade(this.volume,1000);}
 async pause(){const request=++this.token;this.playing=false;this.onState(false,this.city);await this.fade(0,400);if(request===this.token)this.audio.pause();}
}

export function installMusic(){const bar=document.createElement('section');bar.className='music-bar';bar.setAttribute('aria-label','兩地輕音樂');bar.innerHTML='<span class="music-icon" aria-hidden="true">♫</span><div class="music-copy"><span class="music-title">留一點音樂給此刻</span><small id="music-status" aria-live="polite">城市配樂 · 未播放</small></div><div class="music-cities" role="group" aria-label="選擇播放城市"><button data-music-city="paris" class="active" aria-pressed="true">巴黎</button><button data-music-city="taipei" aria-pressed="false">台北</button></div><button id="music-play" aria-label="播放背景音樂" aria-pressed="false">▷ 播放</button><label class="music-volume" for="music-volume">音量<input id="music-volume" type="range" min="0" max="60" value="25" aria-label="背景音樂音量"></label>';
 document.querySelector('footer').before(bar);let selected='paris',intent=false,request=0;const play=bar.querySelector('#music-play'),status=bar.querySelector('#music-status');const update=(playing,city)=>{play.textContent=playing?'Ⅱ 暫停':'▷ 播放';play.setAttribute('aria-pressed',String(playing));play.setAttribute('aria-label',playing?'暫停背景音樂':'播放背景音樂');status.textContent=tracks[city].name+(playing?' · 播放中':' · 已暫停');};const player=new AmbientPlayer(update);
 const start=async()=>{const current=++request;status.textContent='準備音樂…';try{await player.play(selected);if(current!==request&&!intent)await player.pause();}catch(error){if(current===request){intent=false;update(false,selected);status.textContent=error.message||'音樂未能播放，請再試一次';}}};
 bar.querySelectorAll('[data-music-city]').forEach(button=>button.addEventListener('click',()=>{if(selected===button.dataset.musicCity)return;selected=button.dataset.musicCity;bar.querySelectorAll('[data-music-city]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});if(intent)start();else status.textContent=tracks[selected].name+' · 未播放';}));
 play.addEventListener('click',()=>{intent=!intent;if(intent)start();else{request++;player.pause();}});bar.querySelector('#music-volume').addEventListener('input',e=>player.setVolume(Number(e.target.value)/100));window.addEventListener('pagehide',()=>player.pause());return player;
}

